const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('浏览器无法保存，本次仍可正常使用。')}};
let theme=read('tcf-theme','dark'),day='push',mode='beginner',remaining=90,deadline=0,interval=null,sources=[];
function applyTheme(){document.documentElement.classList.toggle('dark',theme==='dark');$('#theme').textContent=theme==='dark'?'☀':'☾';$('#theme').setAttribute('aria-label',theme==='dark'?'切换浅色模式':'切换夜间模式')};applyTheme();$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';save('tcf-theme',theme);applyTheme()};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}
function detail(e){return `<div class="detail-body"><span class="label">${e.muscles}</span><p><b>准备</b>　${e.setup}</p><p><b>动作</b>　${e.motion}</p><p><b>常见错误</b>　${e.error}</p><div class="note"><b>新手调整</b>　${e.beginner}</div></div>`}
function exerciseDetails(e){return `<details id="${e.id}"><summary>${e.name}</summary>${detail(e)}</details>`}
function warmupHtml(d){return warmups[d].map(([t,p])=>`<h3>${t}</h3><p>${p}</p>`).join('')}
function header(title,sub,eyebrow='TRAINING LIBRARY'){return `<div class="wrap page-top"><div class="breadcrumb"><a href="#home">首页</a>　/　${title}</div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>`}
function home(){return `<div class="wrap"><section class="hero"><div><div class="eyebrow">A FIELD GUIDE TO BETTER TRAINING</div><h1>把动作练好，<br><em>把训练练长。</em></h1><p>从推拉腿，到每一次发力。<br>一本可以带进健身房的训练手册，<br>陪你循序渐进，也陪你回到基础。</p><div class="actions"><a class="primary" href="#library">翻开训练手册 →</a><a class="text-link" href="#workout">开始今日训练 ↗</a></div></div><div class="hero-art" aria-label="训练手册书封插画"><div class="back-book"></div><div class="hero-book"><div class="book-en">THE TRAINING MANUAL</div><h2>谭式<br>训练手册</h2><div class="barbell"><b></b><b></b><i></i><b></b><b></b></div><p>动作 · 节奏 · 长期</p></div><span class="art-caption">读懂动作，再开始训练。</span></div></section><div class="principles"><div><small>01</small><strong>动作质量</strong><p>先让每一次可控，再让重量增长。</p></div><div><small>02</small><strong>循序渐进</strong><p>选择适合自己的版本，记录点滴进步。</p></div><div><small>03</small><strong>长期练习</strong><p>把训练与恢复，放回日常生活。</p></div></div><section id="library"><div class="section-head"><div><div class="eyebrow">THE COLLECTION</div><h2>训练手册书架</h2></div><p>七个主题 · 从入门到细节</p></div><div class="shelf">${manuals.map((m,i)=>`<a class="manual-card" href="#manual/${m.id}"><div class="cover" style="--cover:${m.color}"><span class="serial">VOL. 0${i+1}　/　训练知识库</span><h3>${m.title.length>5?m.title.slice(0,4)+'<br>'+m.title.slice(4):m.title}</h3><div class="english">${m.en}</div><span class="glyph" aria-hidden="true">${m.glyph}</span></div><div class="card-body"><p>${m.desc}</p><div class="card-meta"><span>${m.sections.length} 个章节</span><span>开始阅读 →</span></div></div></a>`).join('')}</div></section><section class="start-strip"><div><div class="eyebrow">LESS RUSH. MORE PRACTICE.</div><h2>今天，从一组认真开始。</h2><p>选择推、拉或腿，先热身，再按自己的节奏完成。</p></div><a class="primary" href="#workout">进入今日训练 →</a></section></div>`}
function manual(id){const m=manuals.find(x=>x.id===id);if(!m)return notFound();return header(m.title,m.desc,m.en)+`<div class="reader"><aside class="toc"><strong>本册目录</strong>${m.sections.map(([t],i)=>`<a href="#manual/${id}/s${i}">${String(i+1).padStart(2,'0')}　${t}</a>`).join('')}<a href="#sources/${m.source}">查看对应原文 ↗</a></aside><article><div class="note">整理版 · 动作细节含通用新手教学，原始安排请到技能原文区核对。</div>${m.sections.map(([t,body],i)=>`<section id="s${i}"><h2>${t}</h2>${body}</section>`).join('')}${sourceVideos[m.source]?`<section><h2>原文中的视频线索</h2><p class="subtle">以下链接根据技能记录的 BV 编号生成，尚未逐段核验。</p>${sourceVideos[m.source].map(([t,b])=>`<p><a class="video" target="_blank" rel="noopener noreferrer" href="https://www.bilibili.com/video/${b}/">${t} ↗</a></p>`).join('')}</section>`:''}<div class="actions"><a class="text-link" href="#library">← 返回书架</a><a class="text-link" href="#sources/${m.source}">核对完整原文 →</a></div></article></div>`}
function notFound(){return header('没有找到这本手册','请回到书架选择想阅读的内容。')+'<div class="wrap"><a class="primary" href="#library">返回书架</a></div>'}
function todayKey(){const d=new Date();return `tcf-checks-${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function workout(){const names={push:'推日',pull:'拉日',legs:'腿日'},checked=read(todayKey(),{}),list=exercises.filter(e=>e.day===day);return header('今日训练','先热身，再练习。按身体状态选择训练日，不必赶着完成所有动作。','YOUR DAILY PRACTICE')+`<div class="wrap"><div class="toolbar"><label for="mode">训练视图</label><select id="mode"><option value="beginner" ${mode==='beginner'?'selected':''}>新手练习版</option><option value="original" ${mode==='original'?'selected':''}>技能安排参考</option></select><span class="subtle">${mode==='beginner'?'每个动作先做 1～2 组，保留 2～3 次余力；不要求全部完成。':'显示技能原文组次，不含力竭强化执行；不是新手推荐量。'}</span></div><div class="tabs" role="group" aria-label="训练日">${Object.entries(names).map(([d,n])=>`<button data-day="${d}" class="${d===day?'active':''}" aria-pressed="${d===day}">${n} <span class="subtle">${d.toUpperCase()}</span></button>`).join('')}</div><div class="work-grid"><section><details><summary>训练前热身 · ${names[day]}</summary><div class="detail-body">${warmupHtml(day)}<p class="subtle">通用新手整理流程；热身不做到力竭。</p></div></details>${list.map((e,i)=>`<div class="exercise-row"><input type="checkbox" data-check="${e.id}" aria-label="完成${e.name}" ${checked[e.id]?'checked':''}><details id="${e.id}"><summary><span class="subtle">0${i+1}　</span>${e.name}</summary><div class="prescription">${mode==='original'?e.original:'练习 1～2 组 × '+(e.id==='raise'||e.id==='curl'?'12～15':'8～12')+' 次'}${mode==='beginner'&&['single-rdl','split-squat'].includes(e.id)?' / 侧':''}</div>${detail(e)}</details></div>`).join('')}</section><aside class="work-side"><div><div class="eyebrow">TODAY'S PROGRESS</div><h3>${names[day]}完成情况</h3><div id="progress"></div><p class="subtle">勾选表示完成该动作，不是每一组。记录仅保存在当前浏览器，按自然日区分。</p><button id="reset-checks">重置本日${names[day]}</button></div><div><div class="eyebrow">TAKE A BREATH</div><h3>组间休息</h3><label class="subtle" for="rest">休息时长</label><select id="rest"><option value="60">60 秒</option><option value="90" selected>90 秒</option><option value="120">120 秒</option><option value="180">180 秒</option></select><div class="timer" id="timer">01:30</div><div class="toolbar"><button id="timer-toggle">开始计时</button><button id="timer-reset">重置</button></div><p class="subtle">复合动作通常需要更长休息；按下一组表现调整。</p></div></aside></div></div>`}
function sourcesPage(){return header('技能原文与整理说明','完整收录 1 份技能入口与 6 份参考资料。原文保留原样，整理版单独呈现。','SOURCE COLLECTION')+`<div class="wrap"><div class="note source-note">原文是本地技能的学习笔记，不等同于已核验的视频逐字稿。部分说法、数字和个人资料待核实，不作为个体化训练或饮食处方。</div><div class="source-note"><h2>保留完整内容，也说明适用边界</h2><ul><li>完整性：7 份 Markdown 均可展开阅读或下载，未删改原文。</li><li>整理版：纠正训练频率矛盾，避免把“膝盖不能过脚尖”等绝对化提示当成通用规则。</li><li>新手默认：不包含强化力竭、备赛脱水或统一补剂剂量。</li><li>视频：保留原文所有 BV 编号；本网站未逐段核验视频。</li></ul></div><div class="source-list">${sources.length?sources.map(s=>`<details id="source-${s.file}"><summary>${esc(s.title)}<span>${esc(s.file)}</span></summary><pre>${esc(s.text)}</pre><a href="originals/${encodeURIComponent(s.file)}" download>下载完整 Markdown ↓</a><a target="_blank" href="originals/${encodeURIComponent(s.file)}" rel="noopener">打开原文 ↗</a></details>`).join(''):'<p id="loading-source">正在载入原文…</p>'}</div></div>`}
function fillContent(){document.querySelectorAll('[data-exercises]').forEach(el=>{const v=el.dataset.exercises;el.innerHTML=exercises.filter(e=>v==='all'||e.day===v).map(exerciseDetails).join('')});document.querySelectorAll('[data-exercise]').forEach(el=>{const e=exercises.find(x=>x.id===el.dataset.exercise);el.innerHTML=e?exerciseDetails(e):''});document.querySelectorAll('[data-warmups]').forEach(el=>el.innerHTML=Object.entries({push:'推日',pull:'拉日',legs:'腿日'}).map(([d,t])=>`<details><summary>${t}热身</summary><div class="detail-body">${warmupHtml(d)}</div></details>`).join(''))}
function updateProgress(){const checked=read(todayKey(),{}),n=exercises.filter(e=>e.day===day&&checked[e.id]).length;if($('#progress'))$('#progress').innerHTML=`<strong>${n} / 5 个动作</strong><div class="progress-track"><span style="width:${n*20}%"></span></div>`}
function timerText(){if($('#timer'))$('#timer').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0')}
function stopTimer(){clearInterval(interval);interval=null;deadline=0}
function bindWorkout(){document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=b.dataset.day;render(false)});$('#mode').onchange=e=>{mode=e.target.value;render(false)};document.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>{const all=read(todayKey(),{});all[c.dataset.check]=c.checked;save(todayKey(),all);updateProgress()});$('#reset-checks').onclick=()=>{const all=read(todayKey(),{});exercises.filter(e=>e.day===day).forEach(e=>delete all[e.id]);save(todayKey(),all);render(false)};updateProgress();remaining=90;timerText();$('#rest').onchange=e=>{stopTimer();remaining=+e.target.value;timerText();$('#timer-toggle').textContent='开始计时'};$('#timer-reset').onclick=()=>{stopTimer();remaining=+$('#rest').value;timerText();$('#timer-toggle').textContent='开始计时'};$('#timer-toggle').onclick=()=>{if(interval){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));stopTimer();timerText();$('#timer-toggle').textContent='继续计时';return}if(remaining<=0)remaining=+$('#rest').value;deadline=Date.now()+remaining*1000;$('#timer-toggle').textContent='暂停';interval=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));timerText();if(!remaining){stopTimer();$('#timer-toggle').textContent='再次开始';toast('休息结束，按状态开始下一组。')}},200)}}
function render(scroll=true){stopTimer();const route=location.hash.slice(1)||'home',parts=route.split('/');$('#main').innerHTML=parts[0]==='manual'?manual(parts[1]):parts[0]==='workout'?workout():parts[0]==='sources'?sourcesPage():home();fillContent();if(parts[0]==='workout')bindWorkout();document.title=(parts[0]==='manual'?(manuals.find(m=>m.id===parts[1])?.title||'训练手册'):parts[0]==='workout'?'今日训练':parts[0]==='sources'?'技能原文':'谭式训练手册')+' · Tanchengyi Fitness';if(scroll){window.scrollTo(0,0);requestAnimationFrame(()=>{if(route==='library')$('#library')?.scrollIntoView();if(parts[0]==='manual'&&parts[2]){const el=document.getElementById(parts[2]);if(el){if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView()}}if(parts[0]==='sources'&&parts[1]){const el=document.getElementById('source-'+parts[1]);if(el){el.open=true;el.scrollIntoView()}}})}}
function search(){const q=$('#search').value.trim().toLowerCase();if(!q){$('#results').innerHTML='<p class="empty">搜索动作、肌群、热身或恢复主题。</p>';return}const hits=[];exercises.forEach(e=>{if(Object.values(e).join(' ').toLowerCase().includes(q))hits.push({title:e.name,desc:e.muscles+' · 动作细节',url:'#manual/split/'+e.id})});manuals.forEach(m=>m.sections.forEach(([t,b],i)=>{if((m.title+t+b.replace(/<[^>]+>/g,'')).toLowerCase().includes(q))hits.push({title:t,desc:m.title,url:`#manual/${m.id}/s${i}`})}));sources.forEach(s=>{if(s.text.toLowerCase().includes(q))hits.push({title:s.title,desc:'技能原文 · '+s.file,url:'#sources/'+s.file})});$('#results').innerHTML=hits.length?hits.map(h=>`<a href="${h.url}">${esc(h.title)}<small>${esc(h.desc)}</small></a>`).join(''):'<p class="empty">没有找到相关内容，试试其他关键词。</p>';$('#results').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
$('#search-open').onclick=()=>{$('#search-dialog').showModal();search();$('#search').focus()};$('.close').onclick=()=>$('#search-dialog').close();$('#search').oninput=search;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-open').click()}});window.addEventListener('hashchange',()=>render());render();fetch('sources.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{sources=d;if(location.hash.startsWith('#sources'))render();if($('#search-dialog').open)search()}).catch(()=>{if($('#loading-source'))$('#loading-source').innerHTML='原文暂时未能载入，请刷新重试。';toast('原文载入失败，请刷新重试。')});
